-- Separate, rolled-back paid-MVP deployment stage. Historical deferred-module
-- suites run against the migration schema; this stage closes their public APIs.
\set ON_ERROR_STOP on
begin;
\ir ../../supabase/launch/paid-mvp.sql
create function pg_temp.mvp_assert(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.mvp_reject(statement text,label text)returns void language plpgsql as $$begin begin execute statement;exception when others then return;end;raise exception 'FAIL, unexpectedly allowed: %',label;end$$;
select pg_temp.mvp_assert(dm_private.mvp_profile_permissions_valid(),'exact default-deny application RPC profile');
select pg_temp.mvp_assert((select count(*)=47 from dm_private.mvp_rpc_allowlist),'explicit student/staff permission manifest');
select pg_temp.mvp_assert(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')and has_function_privilege('anon',p.oid,'EXECUTE')),'no anonymous application RPCs');
select pg_temp.mvp_assert(has_function_privilege('service_role','public.fulfil_verified_payment(text,text,text,integer,text)','EXECUTE')and has_function_privilege('supabase_auth_admin','public.before_designmocks_user_created(jsonb)','EXECUTE'),'service capture and controlled Auth hook remain explicitly authorized');
insert into auth.users(id)values('00000000-0000-4000-8000-000000001951'),('00000000-0000-4000-8000-000000001952'),('00000000-0000-4000-8000-000000001953');
insert into dm_private.admins(user_id)values('00000000-0000-4000-8000-000000001951');
\ir fixtures/mvp-objective-paper.sql
select pg_temp.seed_mvp_paper('uceed','10000000-0000-4000-8000-000000001951');
select pg_temp.seed_mvp_paper('ceed','10000000-0000-4000-8000-000000001954');
insert into dm_private.orders(id,user_id,plan_id,amount,currency,mode,provider_order_id)values('20000000-0000-4000-8000-000000001952','00000000-0000-4000-8000-000000001952','annual',119300,'INR','test','order_mvpProfileOriginal');
set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
select public.fulfil_verified_payment('evt_mvpProfileOriginal','order_mvpProfileOriginal','pay_mvpProfileOriginal',119300,'INR');
reset role;
set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000001952',true);
select pg_temp.mvp_assert(public.available_papers()='[]'::jsonb,'unreleased catalogue is empty despite a pass');
select pg_temp.mvp_reject('select public.admin_mvp_paper_manifest(''10000000-0000-4000-8000-000000001951'')','ordinary actor cannot inspect operator manifest');
select pg_temp.mvp_reject('select *from dm_private.mvp_paid_releases','private release records are not directly readable');
select pg_temp.mvp_reject('select public.start_exam_mock(''uceed'')','deferred exam generator is denied');
select pg_temp.mvp_reject('select public.start_topic_practice(''uceed'',''fixture'',10,15)','deferred topic product is denied');
select pg_temp.mvp_reject('select public.learning_catalog()','deferred Learn API is denied');
select pg_temp.mvp_reject('select public.community_feed(null,null)','deferred Community API is denied');
select pg_temp.mvp_reject('select public.public_all_india_top_ten()','deferred public ranking API is denied');
select pg_temp.mvp_reject('select public.start_exam_mock_part_b(gen_random_uuid())','deferred Part B API is denied');
select pg_temp.mvp_reject('select public.start_attempt(''10000000-0000-4000-8000-000000001951'')','paid starts require an approved exact release');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000001951',true);
select pg_temp.mvp_assert((public.admin_mvp_paper_manifest('10000000-0000-4000-8000-000000001951')->>'eligible')::boolean,'complete reviewed canonical Part A can be inspected before publication');
select pg_temp.mvp_assert(public.admin_mvp_paper_manifest('10000000-0000-4000-8000-000000001954')->'manifest'->>'questionCount'='44'and public.admin_mvp_paper_manifest('10000000-0000-4000-8000-000000001954')->'manifest'->>'totalPoints'='150','verified CEED Part A has its own exact counts, marks and clock');
select set_config('test.mvp.sha',public.admin_mvp_paper_manifest('10000000-0000-4000-8000-000000001951')->'manifest'->>'sha256',true);
select pg_temp.mvp_reject('select public.admin_release_mvp_paper(''10000000-0000-4000-8000-000000001951'',repeat(''f'',64),''Fictional owner approval'')','stale manifest cannot release');
select pg_temp.mvp_reject('select public.admin_release_mvp_paper(''10000000-0000-4000-8000-000000001951'',current_setting(''test.mvp.sha''),''short'')','explicit owner rights/provenance reference is required');
select pg_temp.mvp_assert(public.admin_release_mvp_paper('10000000-0000-4000-8000-000000001951',current_setting('test.mvp.sha'),'Fictional owner authorization for original adapted practice material')->>'questionCount'='57','exact 57-question owner decision is recorded');
select pg_temp.mvp_assert((public.admin_launch_readiness()->>'apiProfileReady')::boolean and(public.admin_launch_readiness()->>'offeringReady')::boolean and not(public.admin_launch_readiness()->>'readyForSales')::boolean,'release/API proof alone never clears policy/provider gates');
select pg_temp.mvp_assert(jsonb_array_length(public.admin_launch_readiness()->'gates')=7 and not exists(select 1 from jsonb_array_elements(public.admin_launch_readiness()->'gates')g where g->>'gate'='drawing_operations'),'objective MVP does not require the deferred drawing operation');
select pg_temp.mvp_assert(public.admin_operational_health()->>'scope'='paid-mvp-v1'and public.admin_operational_health()->>'paymentReviews'='0','minimal operational counters are available to the owner without deferred product queues');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000001952',true);
select pg_temp.mvp_assert(jsonb_array_length(public.available_papers())=1,'only the approved unchanged offering is visible');
select set_config('test.mvp.attempt',public.start_attempt('10000000-0000-4000-8000-000000001951')::text,true);
select pg_temp.mvp_assert(public.start_attempt('10000000-0000-4000-8000-000000001951')::text=current_setting('test.mvp.attempt'),'idempotent active start remains on one fixed attempt');
select public.save_answer_revision(current_setting('test.mvp.attempt')::uuid,md5('mvp-original-1')::uuid,'"1"',1);
select pg_temp.mvp_assert(public.submit_attempt(current_setting('test.mvp.attempt')::uuid)->>'score'='4','objective result uses the existing canonical scorer');
reset role;
select pg_temp.mvp_assert((select count(*)=57 from dm_private.attempt_items where attempt_id=current_setting('test.mvp.attempt')::uuid)and(select deadline=started_at+interval'7200 seconds'from dm_private.attempts where id=current_setting('test.mvp.attempt')::uuid),'exact frozen questions and two-hour server clock');
select set_config('test.mvp.frozen',(select md5(jsonb_agg(to_jsonb(i)order by ordinal)::text)from dm_private.attempt_items i where attempt_id=current_setting('test.mvp.attempt')::uuid),true);
select pg_temp.mvp_reject('update dm_private.bank_questions set payload=jsonb_set(payload,''{holds}'',''["human-review"]'')where external_key=''mvp-original-1''','canonical storage itself refuses held material');
update dm_private.bank_questions set active=false where external_key='mvp-original-1';
set local role authenticated;
select pg_temp.mvp_assert(public.available_papers()='[]'::jsonb,'a new canonical hold immediately closes the released offering');
select pg_temp.mvp_reject('select public.start_attempt(''10000000-0000-4000-8000-000000001951'')','held bank content cannot create another attempt');
select pg_temp.mvp_assert(public.read_attempt(current_setting('test.mvp.attempt')::uuid)->>'score'='4','prior owned results survive release closure');
reset role;
update dm_private.bank_questions set active=true where external_key='mvp-original-1';
update dm_private.questions set prompt='Changed after owner review'where id=md5('mvp-original-1')::uuid;
select pg_temp.mvp_assert(not dm_private.mvp_release_is_current('10000000-0000-4000-8000-000000001951'),'question changes invalidate an earlier release');
update dm_private.questions set prompt='Original fictional profile question 1'where id=md5('mvp-original-1')::uuid;
update dm_private.papers set duration_seconds=3600 where id='10000000-0000-4000-8000-000000001951';
select pg_temp.mvp_assert(dm_private.mvp_paper_manifest('10000000-0000-4000-8000-000000001951')is null,'wrong clock cannot impersonate a complete Part A');
update dm_private.papers set duration_seconds=7200,title='Original fictional full UCEED exam'where id='10000000-0000-4000-8000-000000001951';
select pg_temp.mvp_assert(dm_private.mvp_paper_manifest('10000000-0000-4000-8000-000000001951')is null,'the initial offer must explicitly identify Part A');
update dm_private.papers set title='UCEED Part A original fictional profile paper'where id='10000000-0000-4000-8000-000000001951';
update dm_private.launch_gate_attestations set approved=true,evidence='Fictional reviewed MVP acceptance'where gate<>'drawing_operations';
update public.launch_settings set policy_version='fictional-mvp-profile';
select pg_temp.mvp_reject('update public.launch_settings set sales_enabled=true','merchant Test acceptance cannot open live sales');
update public.launch_settings set environment_mode='live';
update public.launch_settings set sales_enabled=true;
select pg_temp.mvp_assert((select sales_enabled from public.launch_settings),'only the exact offering plus all MVP evidence allows the private sales guard');
create function public.future_unreviewed_mvp_rpc()returns void language plpgsql as $$begin return;end$$;
select pg_temp.mvp_assert(not dm_private.mvp_profile_permissions_valid(),'future unexpected client grants invalidate API release controls');
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000001951',true);
select pg_temp.mvp_assert(not(public.admin_launch_readiness()->>'readyForSales')::boolean,'a stale API profile cannot show green readiness');
reset role;drop function public.future_unreviewed_mvp_rpc();
update public.launch_settings set sales_enabled=false;
set local role authenticated;
select public.admin_withdraw_mvp_paper('10000000-0000-4000-8000-000000001951',current_setting('test.mvp.sha'),'Fictional withdrawal for owner review');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000001952',true);
select pg_temp.mvp_assert(public.available_papers()='[]'::jsonb,'withdrawal prevents new selection');
select pg_temp.mvp_reject('select public.start_attempt(''10000000-0000-4000-8000-000000001951'')','withdrawal prevents new starts');
select pg_temp.mvp_assert(public.read_attempt(current_setting('test.mvp.attempt')::uuid)->>'score'='4','withdrawal preserves the owned customer result');
reset role;
select pg_temp.mvp_assert((select count(*)=2 from dm_private.mvp_release_audit),'release and withdrawal append actor/evidence audit');
select pg_temp.mvp_assert((select md5(jsonb_agg(to_jsonb(i)order by ordinal)::text)from dm_private.attempt_items i where attempt_id=current_setting('test.mvp.attempt')::uuid)=current_setting('test.mvp.frozen'),'release changes never rewrite frozen attempt contents');
\ir ../../supabase/launch/paid-mvp.sql
select pg_temp.mvp_assert(dm_private.mvp_profile_permissions_valid()and(select count(*)=2 from dm_private.mvp_release_audit),'profile reapplication is idempotent and preserves approvals/audit');
rollback;
\echo 'PASS: paid MVP default-deny APIs, canonical exact-paper approval, holds/snapshots, guarded sales and preserved owned results.'
